function neuCss(o){
  o=o||{};
  var bg=o.bg||'#e0e0e0';
  var dist=(+o.distance); if(isNaN(dist))dist=12;
  var r=(+o.radius); if(isNaN(r))r=24;
  var inten=(+o.intensity); if(isNaN(inten))inten=0.15;
  var dark='rgba(0,0,0, '+inten.toFixed(2)+')';
  var light='rgba(255,255,255, '+(inten*0.9).toFixed(2)+')';
  return 'background: '+bg+';\n'+
    'border-radius: '+r+'px;\n'+
    'box-shadow: '+dist+'px '+dist+'px '+(dist*2)+'px '+dark+',\n'+
    '             -'+dist+'px -'+dist+'px '+(dist*2)+'px '+light+';';
}
var EXPORTS={neuCss:neuCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NeumorphismForgePure = EXPORTS; }
